const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const sakurajima = ee.Geometry.Point([130.657, 31.596]); // Sakurajima Volcano location

    // Geometries to test the two plume path hypotheses
    // Path 1: First East, then South
    const eastPoint = ee.Geometry.Point([130.95, 31.60]); // Approx 27 km East
    const southEastPoint1 = ee.Geometry.Point([130.95, 31.30]); // Approx 33 km South from the east point

    // Path 2: First South, then East
    const southPoint = ee.Geometry.Point([130.65, 31.30]); // Approx 33 km South
    const southEastPoint2 = ee.Geometry.Point([130.95, 31.30]); // Same as southEastPoint1, but approached from the south point

    const startDate = '2015-05-21';
    const endDate = '2015-05-23'; // Look at eruption day and day after for plume transport

    // 2. Data Acquisition & Check
    // MODIS Aerosol Optical Depth (AOD) is suitable for tracking ash plumes.
    let modisAOD = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
        .filterDate(startDate, endDate)
        .filterBounds(sakurajima.buffer(100000)); // Buffer to ensure we get images covering the area

    if (modisAOD.size().getInfo() === 0) {
        console.log("No MODIS AOD images found for the specified date range and location.");
        console.log("A: No"); // If no data, the hypothesis cannot be confirmed.
        return;
    }

    // Select the AOD band and create a single composite image for analysis
    // We use a max composite to capture the highest AOD values, which likely represent the densest part of the plume.
    const aodImage = modisAOD.select('Optical_Depth_047').max();

    // 3. Processing
    const scale = 1000; // MODIS resolution for this product is 1km

    // Function to get mean AOD and pixel count for a given geometry
    const getAodStats = (point, label) => {
        const stats = aodImage.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: point.buffer(5000), // Buffer the point to create a small region for analysis
            scale: scale,
            maxPixels: 1e9
        });
        const mean = ee.Number(stats.get('Optical_Depth_047_mean')).multiply(1000); // Scale for readability
        const count = ee.Number(stats.get('Optical_Depth_047_count'));
        return {
            mean: mean.getInfo(),
            count: count.getInfo(),
            label: label
        };
    };

    const eastStats = getAodStats(eastPoint, 'East');
    const southStats = getAodStats(southPoint, 'South');
    const southEastStats = getAodStats(southEastPoint1, 'South-East'); // Same point for both paths

    // 4. Validation & Final Answer
    console.log(`Image Count: ${modisAOD.size().getInfo()}`);
    console.log(`AOD (x1000) at East Point: ${eastStats.mean ? eastStats.mean.toFixed(2) : 'N/A'} (Pixels: ${eastStats.count})`);
    console.log(`AOD (x1000) at South Point: ${southStats.mean ? southStats.mean.toFixed(2) : 'N/A'} (Pixels: ${southStats.count})`);
    console.log(`AOD (x1000) at South-East Point: ${southEastStats.mean ? southEastStats.mean.toFixed(2) : 'N/A'} (Pixels: ${southEastStats.count})`);

    // Check for C2/C3 cases
    if (eastStats.count === 0 || southStats.count === 0 || southEastStats.count === 0) {
        console.log("No valid pixels in one or more analysis regions.");
        console.log("C2");
        return;
    }
    if (eastStats.mean === null || southStats.mean === null || southEastStats.mean === null) {
        console.log("Calculation failed, resulted in null AOD values.");
        console.log("C3");
        return;
    }

    // Logic: "First east then south" implies AOD is high at the east point and the south-east point,
    // while the south point has lower AOD.
    // "First south then east" implies AOD is high at the south point and the south-east point,
    // while the east point has lower AOD.
    // We check if AOD_east > AOD_south, which supports the "first east" hypothesis.
    // Both paths end at the same SE point, so we look at the initial direction.
    const firstEastThenSouth = eastStats.mean > southStats.mean && southEastStats.mean > southStats.mean;

    if (firstEastThenSouth) {
        console.log("Evidence supports plume moving east, then turning south.");
        console.log("A");
    } else {
        console.log("Evidence does not support an initial eastward plume movement over a southward one.");
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log("D");
});
